// Golden + invariant tests for tagBlunder.
//
// Fixtures in fixtures/tagBlunderFixtures.json are generated by
//   node server/scripts/generate_tagblunder_fixtures.mjs
// from REAL game positions (gameSampling.harvestBlunders — never hand-crafted),
// one set per reachable tag:direction. Two layers of checking:
//
//   1. Golden/regression — tagBlunder reproduces the recorded tag+direction for
//      every fixture (catches unintended behavioral drift).
//   2. Structural invariants — properties that must hold from board geometry alone
//      (no solver), independent of how the fixture was produced (catches mislabels).
//
// Plus Phase-0 precondition tests for NotABlunderError.

import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import {
  tagBlunder,
  NotABlunderError,
  Board,
} from '../../server/classifier.js';
import { simulateGame } from '../../server/gameSampling.js';
import { VALID_BLUNDER_TAGS } from '../../server/blunderTags.js';
import { createSolverProcess } from '../../server/c4solver-wrapper.js';

const __dir = dirname(fileURLToPath(import.meta.url));
const fixtures = JSON.parse(
  readFileSync(join(__dir, 'fixtures', 'tagBlunderFixtures.json'), 'utf8')
);

// 'forfeited_win' added spec 052 US3 (Decision D4): a refinement of 'drawing_move's
// direction field, distinguishing "forfeited a forced win" from the genuine
// best-is-a-draw case ('missed_own', unchanged) — no new pattern_category, no migration.
const VALID_DIRECTIONS = new Set(['missed_own', 'enabled_opponent', 'defensive_miss', 'forfeited_win']);

// blunderer = whoever is to move at boardState (even move count → Red opens)
const blundererOf = (boardState) => (boardState.length % 2 === 0 ? 1 : 2);

// ─────────────────────────────────────────────────────────────────────────────
// Layer 1 — golden/regression: tagBlunder reproduces each recorded verdict.
// ─────────────────────────────────────────────────────────────────────────────
describe('tagBlunder fixtures — golden regression', () => {
  let solver;
  before(() => { solver = createSolverProcess(); });
  after(() => { solver.destroy(); });

  for (const fx of fixtures) {
    it(`${fx.bin} @ "${fx.boardState}" (played ${fx.playedCol}, correct ${fx.correctCol})`, async () => {
      const result = await tagBlunder(fx.boardState, fx.playedCol, fx.correctCol, solver);
      assert.equal(result.tag, fx.expectedTag, `tag mismatch (reason: ${result.reason})`);
      assert.equal(result.direction, fx.expectedDirection, `direction mismatch (reason: ${result.reason})`);
    }, { timeout: 60_000 });
  }
});

// ─────────────────────────────────────────────────────────────────────────────
// Layer 2 — structural invariants (board geometry only, no solver).
// ─────────────────────────────────────────────────────────────────────────────
describe('tagBlunder fixtures — structural invariants', () => {
  it('every fixture has a valid tag and direction', () => {
    assert.ok(fixtures.length > 0, 'fixture set must not be empty');
    for (const fx of fixtures) {
      assert.ok(VALID_BLUNDER_TAGS.has(fx.expectedTag), `invalid tag: ${fx.expectedTag}`);
      assert.ok(VALID_DIRECTIONS.has(fx.expectedDirection), `invalid direction: ${fx.expectedDirection}`);
      assert.equal(`${fx.expectedTag}:${fx.expectedDirection}`, fx.bin);
    }
  });

  it('immediate_threat:missed_own ⇒ blunderer actually had an immediate win', () => {
    for (const fx of fixtures) {
      if (fx.bin !== 'immediate_threat:missed_own') continue;
      const board = new Board(fx.boardState);
      const blunderer = blundererOf(fx.boardState);
      assert.ok(
        board.immediateThreats(blunderer).length > 0,
        `"${fx.boardState}": blunderer (P${blunderer}) should have an immediate winning column`
      );
    }
  });

  it('forced_block:defensive_miss ⇒ opponent already had an immediate threat', () => {
    for (const fx of fixtures) {
      if (fx.bin !== 'forced_block:defensive_miss') continue;
      const board = new Board(fx.boardState);
      const opponent = 3 - blundererOf(fx.boardState);
      assert.ok(
        board.immediateThreats(opponent).length > 0,
        `"${fx.boardState}": opponent (P${opponent}) should have a pre-existing immediate threat`
      );
    }
  });

  it('defensive_miss is only ever paired with the forced_block tag', () => {
    for (const fx of fixtures) {
      if (fx.expectedDirection !== 'defensive_miss') continue;
      assert.equal(fx.expectedTag, 'forced_block',
        `defensive_miss must pair with forced_block, got ${fx.expectedTag}`);
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// Phase 0 — precondition: NotABlunderError on terminal positions.
// ─────────────────────────────────────────────────────────────────────────────
describe('tagBlunder — Phase 0 precondition', () => {
  it('throws NotABlunderError on an already-won position (sourced from the simulator)', async () => {
    const solver = createSolverProcess();
    try {
      // simulateGame plays to a win/full board, so its final movestring is terminal.
      const { ms } = await simulateGame(solver);
      const board = new Board(ms);
      assert.ok(
        board.hasWon(1) || board.hasWon(2) || ms.length >= 42,
        'simulated game should end terminal'
      );
      await assert.rejects(
        () => tagBlunder(ms, 0, 0, solver),
        (err) => err instanceof NotABlunderError,
        'tagBlunder must throw NotABlunderError on a terminal position'
      );
    } finally {
      solver.destroy();
    }
  }, { timeout: 60_000 });

  it('throws NotABlunderError on a full 42-move board', async () => {
    // Fill each column fully in sequence — always a valid movestring (never overflows)
    // and reaches 42 discs. Phase 0 throws before any solver call.
    const fullBoard = '000000111111222222333333444444555555666666';
    assert.equal(fullBoard.length, 42);
    const solver = createSolverProcess();
    try {
      await assert.rejects(
        () => tagBlunder(fullBoard, 0, 0, solver),
        (err) => err instanceof NotABlunderError
      );
    } finally {
      solver.destroy();
    }
  }, { timeout: 30_000 });
});
